declare_lint ! { #[doc = " The `let_underscore_drop` lint checks for statements which don't bind"] #[doc = " an expression which has a non-trivial Drop implementation to anything,"] #[doc = " causing the expression to be dropped immediately instead of at end of"] #[doc = " scope."] #[doc = ""] #[doc = " ### Example"] #[doc = ""] #[doc = " ```rust"] #[doc = " struct SomeStruct;"] #[doc = " impl Drop for SomeStruct {"] #[doc = "     fn drop(&mut self) {"] #[doc = "         println!(\"Dropping SomeStruct\");"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " fn main() {"] #[doc = "    #[warn(let_underscore_drop)]"] #[doc = "     // SomeStruct is dropped immediately instead of at end of scope,"] #[doc = "     // so \"Dropping SomeStruct\" is printed before \"end of main\"."] #[doc = "     // The order of prints would be reversed if SomeStruct was bound to"] #[doc = "     // a name (such as \"_foo\")."] #[doc = "     let _ = SomeStruct;"] #[doc = "     println!(\"end of main\");"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " {{produces}}"] #[doc = ""] #[doc = " ### Explanation"] #[doc = ""] #[doc = " Statements which assign an expression to an underscore causes the"] #[doc = " expression to immediately drop instead of extending the expression's"] #[doc = " lifetime to the end of the scope. This is usually unintended,"] #[doc = " especially for types like `MutexGuard`, which are typically used to"] #[doc = " lock a mutex for the duration of an entire scope."] #[doc = ""] #[doc = " If you want to extend the expression's lifetime to the end of the scope,"] #[doc = " assign an underscore-prefixed name (such as `_foo`) to the expression."] #[doc = " If you do actually want to drop the expression immediately, then"] #[doc = " calling `std::mem::drop` on the expression is clearer and helps convey"] #[doc = " intent."] pub LET_UNDERSCORE_DROP , Allow , "non-binding let on a type that has a destructor" }